"""Shared primitives for the CrossCheck replay contract.

Holds the topology model, the routing plan model and the exact integer
agreement-band selection described in PROTOCOL.md.  Everything here is pure
standard-library code so the replay stays deterministic and side effect free.
"""

UNIT = 1000000


def is_int(value):
    """Schema integer test: booleans are not integers anywhere."""
    return type(value) is int


def counter_keys(names, src, dst):
    """Return the ordered report keys of directed flow ``src -> dst``.

    The first entry is the report produced by the flow source, the second the
    report produced by the flow destination.  External flows expose exactly one
    report, oriented as ``origination``/``termination``.
    """
    if src == -1:
        return (f"low_{names[dst]}_origination",)
    if dst == -1:
        return (f"low_{names[src]}_termination",)
    return (f"low_{names[src]}_egress_to_{names[dst]}",
            f"low_{names[dst]}_ingress_from_{names[src]}")


class Flow:
    """One directed flow (internal link direction or external interface)."""

    __slots__ = ("index", "src", "dst", "pair", "cap", "reports", "keys", "routers")

    def __init__(self, index, src, dst, cap, reports):
        self.index = index
        self.src = src
        self.dst = dst
        self.pair = (src, dst)
        self.cap = cap
        self.reports = reports          # ordered baseline report keys
        self.keys = tuple(reports)      # published counter keys
        self.routers = tuple(n for n in (src, dst) if n != -1)


class Topology:
    """Canonical flow set, counter-key universe and router incidences."""

    def __init__(self, spec):
        self.spec = spec
        names = {}
        ext_cap = {}
        for node in spec["nodes"]:
            nid = node["id"]
            names[nid] = node["name"]
            ext_cap[nid] = node["external_capacity"]
        self.names = names
        self.name_to_id = {name: nid for nid, name in names.items()}
        self.external = [self.name_to_id[name] for name in spec["external_nodes"]]
        self.external_set = frozenset(self.external)
        self.ext_cap = ext_cap

        raw = []
        for link in spec["links"]:
            s, d, cap = link["source"], link["target"], link["capacity"]
            for a, b in ((s, d), (d, s)):
                raw.append((a, b, cap, counter_keys(names, a, b)))
        for nid in self.external:
            cap = ext_cap[nid]
            raw.append((-1, nid, cap, counter_keys(names, -1, nid)))
            raw.append((nid, -1, cap, counter_keys(names, nid, -1)))

        raw.sort(key=lambda item: item[0:2])
        self.flows = [Flow(i, a, b, cap, reports)
                      for i, (a, b, cap, reports) in enumerate(raw)]
        self.flow_index = {f.pair: i for i, f in enumerate(self.flows)}

        self.key_to_flow = {}
        self.key_cap = {}
        for f in self.flows:
            for key in f.keys:
                self.key_to_flow[key] = f.index
                self.key_cap[key] = f.cap

        # Router incidence tables: node ids that actually route (the external
        # sentinel is not a router).
        self.router_ids = sorted({n for f in self.flows for n in f.routers})
        self.router_of = {nid: r for r, nid in enumerate(self.router_ids)}
        self.router_flows = [[] for _ in self.router_ids]
        self.router_signs = [[] for _ in self.router_ids]
        self.flow_slots = [[] for _ in self.flows]
        for r, nid in enumerate(self.router_ids):
            for f in self.flows:
                if nid not in f.routers:
                    continue
                pos = len(self.router_flows[r])
                self.router_flows[r].append(f.index)
                sign = 1 if f.src == nid else -1
                self.router_signs[r].append(sign)
                self.flow_slots[f.index].append((r, pos))
        for r in range(len(self.router_ids)):
            self.router_flows[r] = tuple(self.router_flows[r])
            self.router_signs[r] = tuple(self.router_signs[r])
            self.flow_slots[r] = tuple(self.flow_slots[r])

    def demand_bound(self, src, dst):
        """Capacity bound honourable by a demand pair, or None when invalid."""
        if src == dst or src not in self.external_set or dst not in self.external_set:
            return None
        a = self.ext_cap[src]
        b = self.ext_cap[dst]
        return a if a < b else b


class Plan:
    """A routing plan normalised for both prediction and cache identity."""

    __slots__ = ("bundle_hops", "identity", "hops")

    def __init__(self, paths, topology):
        entries = []
        bundles = {}
        hops = {}
        if paths is not None:
            for src_name, per_dest in paths.items():
                src = topology.name_to_id[src_name]
                for dst_name, bundle in per_dest.items():
                    dst = topology.name_to_id[dst_name]
                    acc = bundles.get((src, dst))
                    if acc is None:
                        acc = bundles[(src, dst)] = {}
                    for item in bundle:
                        seq = item["path"]
                        ids = tuple(topology.name_to_id[name] for name in seq)
                        weight = item["weight"]
                        entries.append((src, dst, ids, weight))
                        for a, b in zip(ids, ids[1:]):
                            fi = topology.flow_index[(a, b)]
                            acc[fi] = acc.get(fi, 0) + weight
                            hops[fi] = True
        self.bundle_hops = bundles
        self.hops = tuple(sorted(hops))
        self.identity = tuple(sorted(entries))

    def internal_loads(self, demands):
        """Return {flow_index: weighted_sum} before the single final floor."""
        acc = {}
        for (src, dst), value in demands.items():
            if not value:
                continue
            bundle = self.bundle_hops.get((src, dst))
            if not bundle:
                continue
            for fi, weight in bundle.items():
                acc[fi] = acc.get(fi, 0) + value * weight
        return acc


def select_band(counts, epsilon):
    """Winning agreement band of a weighted integer multiset.

    ``counts`` maps nonnegative integer values to positive integer weights.
    Returns ``(representative, mass)`` where the band maximises total weight,
    then smallest lo, then smallest hi, obeys
    ``1000000 * (hi - lo) <= epsilon * hi`` and the representative is the floor
    of the weighted mean of the band entries.
    """
    values = sorted(counts)
    size = len(values)
    best_mass = -1
    best_rep = 0
    j = -1
    mass = 0
    total = 0
    for i in range(size):
        if j < i:
            j = i - 1
            mass = 0
            total = 0
        else:
            lo_prev = values[i - 1]
            w = counts[lo_prev]
            mass -= w
            total -= lo_prev * w
        lo = values[i]
        while True:
            nxt = j + 1
            if nxt >= size:
                break
            hi = values[nxt]
            if UNIT * (hi - lo) > epsilon * hi:
                break
            w = counts[hi]
            mass += w
            total += hi * w
            j = nxt
        if mass > best_mass:
            best_mass = mass
            best_rep = total // mass
    return best_rep, best_mass
